/usr/bin/bash -lc "python - <<'PY'
import ast, pathlib
bad=[]
for p in sorted(pathlib.Path('emovec').glob('*.py'))+sorted(pathlib.Path('tests').glob('*.py')):
    try:
        ast.parse(p.read_text(), filename=str(p))
    except SyntaxError as e:
        bad.append((str(p), e.lineno, e.msg))
print('ast_parse_ok' if not bad else bad)
PY"

